    position.setLongitude(parser.nextCoordinate(Parser.CoordinateFormat.DEG_HEM));
    position.setSpeed(UnitsConverter.knotsFromKph(parser.nextDouble(0)));
    position.setCourse(parser.nextDouble(0));
    position.setAltitude(parser.nextDouble(0));

    position.set(Position.KEY_SATELLITES, parser.nextInt(0));
    position.set(Position.KEY_RSSI, parser.nextInt(0));
    position.set(Position.KEY_BATTERY_LEVEL, parser.nextInt(0));

    position.set(Position.KEY_STEPS, parser.nextInt(0));

    // Fix: Parse status as a string and convert it to an integer with a different radix
    String statusStr = parser.next();
    int status;
    try {
        status = Integer.parseInt(statusStr, 16); // Parse as hexadecimal
    } catch (NumberFormatException e) {
        status = 0; // Default to 0 if parsing fails
    }
    position.set(Position.KEY_ALARM, decodeAlarm(status));
    if (BitUtil.check(status, 4)) {
        position.set(Position.KEY_MOTION, true);
    }

    String[] values = parser.next().split(",");
    int index = 0;

    Network network = new Network();

    int cellCount = Integer.parseInt(values[index++]);
    if (cellCount > 0) {
        index += 1; // timing advance
        int mcc = !values[index].isEmpty() ? Integer.parseInt(values[index++]) : 0;
        int mnc = !values[index].isEmpty() ? Integer.parseInt(values[index++]) : 0;

        for (int i = 0; i < cellCount; i++) {
            int lac = Integer.parseInt(values[index++]);
            int cid = Integer.parseInt(values[index++]);
            String rssi = values[index++];
            if (!rssi.isEmpty()) {
                network.addCellTower(CellTower.from(mcc, mnc, lac, cid, Integer.parseInt(rssi)));
            } else {
                network.addCellTower(CellTower.from(mcc, mnc, lac, cid));
            }
        }
    }

    if (index < values.length && !values[index].isEmpty()) {
        int wifiCount = Integer.parseInt(values[index++]);

        for (int i = 0; i < wifiCount; i++) {
            index += 1; // wifi name
            String macAddress = values[index++];
            String rssi = values[index++];
            if (!macAddress.isEmpty() && !macAddress.equals("0") && !rssi.isEmpty()) {
                network.addWifiAccessPoint(WifiAccessPoint.from(macAddress, Integer.parseInt(rssi)));
            }
        }
    }

    if (network.getCellTowers() != null || network.getWifiAccessPoints() != null) {
        position.setNetwork(network);
    }

    return position;
}
