            position.set(Position.KEY_EVENT, buf.readUnsignedByte()); // reason
            position.set(Position.KEY_ARCHIVE, buf.readUnsignedByte() > 0);
        }

        if (type == MSG_GPS_LBS_3) {
            int module = buf.readUnsignedShort();
            int subLength = buf.readUnsignedByte();
            switch (module) {
                case 0x0027:
                    position.set(Position.KEY_POWER, buf.readUnsignedShort() * 0.01);
                    break;
                case 0x002E:
                    position.set(Position.KEY_ODOMETER, buf.readUnsignedInt());
                    break;
                case 0x003B:
                    position.setAccuracy(buf.readUnsignedShort() * 0.01);
                    break;
                default:
                    buf.skipBytes(subLength);
                    break;
            }
        }

        if (buf.readableBytes() == 4 + 6) {
            position.set(Position.KEY_ODOMETER, buf.readUnsignedInt());
        }

    } else if (type == MSG_ALARM) {

        boolean extendedAlarm = dataLength > 7;
        if (extendedAlarm) {
            decodeGps(position, buf, false, false, false, deviceSession.get(DeviceSession.KEY_TIMEZONE));
        } else {
            DateBuilder dateBuilder = new DateBuilder((TimeZone) deviceSession.get(DeviceSession.KEY_TIMEZONE))
                    .setDate(buf.readUnsignedByte(), buf.readUnsignedByte(), buf.readUnsignedByte())
                    .setTime(buf.readUnsignedByte(), buf.readUnsignedByte(), buf.readUnsignedByte());
            getLastLocation(position, dateBuilder.getDate());
        }
        short alarmType = buf.readUnsignedByte();
        switch (alarmType) {
            case 0x01:
                position.set(Position.KEY_ALARM, Position.ALARM_SOS);
                break;
            case 0x80:
                position.set(Position.KEY_ALARM, Position.ALARM_VIBRATION);
                break;
            case 0x87:
                position.set(Position.KEY_ALARM, Position.ALARM_OVERSPEED);
                break;
            case 0x90:
                position.set(Position.KEY_ALARM, Position.ALARM_ACCELERATION);
                break;
            case 0x91:
                position.set(Position.KEY_ALARM, Position.ALARM_BRAKING);
                break;
            case 0x92:
                position.set(Position.KEY_ALARM, Position.ALARM_CORNERING);
                break;
            case 0x93:
                position.set(Position.KEY_ALARM, Position.ALARM_ACCIDENT);
                break;
            default:
                position.set(Position.KEY_ALARM, Position.ALARM_GENERAL);
                break;
        }

    } else {

        if (dataLength > 0) {
            buf.skipBytes(dataLength);
        }
        if (type != MSG_COMMAND_0 && type != MSG_COMMAND_1 && type != MSG_COMMAND_2) {
            sendResponse(channel, false, type, buf.getShort(buf.writerIndex() - 6), null);
        }
        return null;

    }

    if (hasLanguage(type)) {
        buf.readUnsignedShort();
    }

    if (type == MSG_GPS_LBS_STATUS_3 || type == MSG_FENCE_MULTI) {
        position.set(Position.KEY_GEOFENCE, buf.readUnsignedByte());
    }

    sendResponse(channel, false, type, buf.getShort(buf.writerIndex() - 6), null);

    return position;
}
